$unfilled=count(array_filter($monthRows,fn($r)=>$r['attendance']==='belum'));
$q=db()->prepare("SELECT s.*,i.name imam_name FROM schedules s JOIN imams i ON i.id=s.imam_id WHERE s.prayer_date=? ORDER BY FIELD(s.prayer,'Subuh','Dzuhur','Ashar','Maghrib','Isya')");$q->execute([$day]);$today=$q->fetchAll();
$imams=all_imams(true);
$pageTitle='Ringkasan pengurus';$active='dashboard';require __DIR__.'/partials/admin_header.php';
